 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    def edge_runs(side):
        values = grid[0] if side == 'top' else grid[-1] if side == 'bottom' else ([row[0] for row in grid] if side == 'left' else [row[-1] for row in grid])
        runs, i = [], 0
        while i < len(values):
            if values[i] == background:
                i += 1
                continue
            j = i + 1
            while j < len(values) and values[j] == values[i]:
                j += 1
            if j - i >= 2:
                runs.append((values[i], i, j))
            i = j
        return runs

    edges = {side: edge_runs(side) for side in ('top', 'bottom', 'left', 'right')}
    bars = set()
    for side, runs in edges.items():
        for _, start, end in runs:
            for i in range(start, end):
                if side == 'top': bars.add((0, i))
                elif side == 'bottom': bars.add((h - 1, i))
                elif side == 'left': bars.add((i, 0))
                else: bars.add((i, w - 1))

    pairs = []
    for first, second in (('top', 'bottom'), ('left', 'right')):
        for color1, a0, a1 in edges[first]:
            for color2, b0, b1 in edges[second]:
                if color1 == color2 and a1-a0 == b1-b0:
                    pairs.append((first, a0, a1, second, b0, b1))

    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != background and (r, c) not in bars]
    for r, c, color in markers:
        for a, a0, a1, b, b0, b1 in pairs:
            axis = c if a in ('top', 'bottom') else r
            if a0 <= axis < a1:
                own, other, mapped = a, b, b0 + axis - a0
            elif b0 <= axis < b1:
                own, other, mapped = b, a, a0 + axis - b0
            else:
                continue

            # Connect the marker to its matching edge run.
            if own == 'top':
                ray = ((y, c) for y in range(1, r))
            elif own == 'bottom':
                ray = ((y, c) for y in range(h-2, r, -1))
            elif own == 'left':
                ray = ((r, x) for x in range(1, c))
            else:
                ray = ((r, x) for x in range(w-2, c, -1))
            for y, x in ray:
                if grid[y][x] != background:
                    break
                out[y][x] = color

            # Extend the matching slot from its paired bar across the interior.
            if other == 'top':
                ray = ((y, mapped) for y in range(1, h-1))
            elif other == 'bottom':
                ray = ((y, mapped) for y in range(h-2, 0, -1))
            elif other == 'left':
                ray = ((mapped, x) for x in range(1, w-1))
            else:
                ray = ((mapped, x) for x in range(w-2, 0, -1))
            for y, x in ray:
                if grid[y][x] != background:
                    break
                out[y][x] = color

            # Active markers are changed to the hit color.
            out[r][c] = 4
            break
    return out

if __name__ == '__main__':
    import json
    g = [[9]*22 for _ in range(7)]
